                            aria-hidden="true"
                          >
                            <span className="text-3xl">🕌</span>
                          </div>
                        )}

                        <div className="flex-1 min-w-0">
                          <h2 className="text-white font-extrabold text-lg leading-tight">
                            {mosque.name}
                          </h2>
                          {mosque.tagline && (
                            <p className="text-slate-400 text-xs mt-1 italic leading-snug">
                              {mosque.tagline}
