}

export default function MosqueLandingPage() {
  const params = useParams();
  const slug = params.slug as string;

  const [mosque, setMosque] = useState<any>(null);
  const [notFound, setNotFound] = useState(false);
  const [announcements, setAnnouncements] = useState<any[]>([]);
  const [events, setEvents] = useState<any[]>([]);
  const [officers, setOfficers] = useState<{ role: string; name: string }[]>([]);
  const [qrisUrl, setQrisUrl] = useState("");
  const [slides, setSlides] = useState<any[]>([]);
  const [currentSlide, setCurrentSlide] = useState(0);
  const [prayerTimes, setPrayerTimes] = useState<any>(null);

  const [time, setTime] = useState("");
  const [isFriday, setIsFriday] = useState(false);
  const [nextPrayer, setNextPrayer] = useState("");
  const [countdown, setCountdown] = useState("");
  const [iqomahCountdown, setIqomahCountdown] = useState(300);
  const [showAdzan, setShowAdzan] = useState(false);
  const [currentPrayer, setCurrentPrayer] = useState("");
  const [showPrayerMode, setShowPrayerMode] = useState(false);

  const push = usePushNotification(mosque?.id);

  // SW registration and permission request
  useEffect(() => {
    if (typeof window !== "undefined") {
      if ("serviceWorker" in navigator) {
        navigator.serviceWorker
          .register("/sw.js")
          .then((reg) => {
            console.log("SW PWA registered on scope:", reg.scope);
          })
          .catch((err) => {
            console.error("SW PWA registration failed:", err);
          });
      }
      if ("Notification" in window && Notification.permission === "default") {
        Notification.requestPermission();
      }
    }
  }, []);

  const showLocalNotification = (title: string, body: string) => {
    console.log("Attempting to show notification:", title, body);
    if (typeof window !== "undefined" && "Notification" in window && Notification.permission === "granted") {
      navigator.serviceWorker.ready
        .then((registration) => {
          registration
            .showNotification(title, {
              body: body,
              icon: mosque?.logo_url || "/icons/icon-192.svg",
              badge: "/icons/icon-192.svg",
              vibrate: [100, 50, 100],
              tag: "smartmasjid-pwa-notification",
              renotify: true,
              data: { url: window.location.href },
            } as any)
            .catch((err) => {
              console.error("ServiceWorker showNotification failed:", err);
              new Notification(title, {
                body: body,
                icon: mosque?.logo_url || "/icons/icon-192.svg",
                tag: "smartmasjid-pwa-notification",
                data: { url: window.location.href },
              } as NotificationOptions);
            });
        })
        .catch((err) => {
          console.error("ServiceWorker ready failed:", err);
          new Notification(title, {
            body: body,
            icon: mosque?.logo_url || "/icons/icon-192.svg",
            tag: "smartmasjid-pwa-notification",
            data: { url: window.location.href },
          } as NotificationOptions);
        });
    } else {
      console.warn("Notification permission not granted or unsupported.");
    }
  };

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const triggeredRef = useRef<string | null>(null);

  const refreshPrayerTimes = useCallback(async (city: string) => {
    if (!city?.trim()) return;
    try {
      setPrayerTimes(await fetchPrayerTimes(city.trim()));
    } catch {
      setPrayerTimes(null);
    }
  }, []);

  useEffect(() => {
    if (!slug) return;
    const load = async () => {
      const { data: mosqueData, error } = await supabase
        .from("mosques")
        .select("*")
        .eq("slug", slug)
        .single();
      if (error || !mosqueData) {
        setNotFound(true);
        return;
      }
      setMosque(mosqueData);
      if (mosqueData.iqomah_duration) setIqomahCountdown(mosqueData.iqomah_duration);
      const id = mosqueData.id;
      const today = new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Jakarta" });

      const [annRes, evRes, offRes, qrisRes, slidesRes] = await Promise.all([
        supabase
          .from("announcements")
          .select("*")
          .eq("mosque_id", id)
          .order("created_at", { ascending: false })
          .limit(5),
        supabase
          .from("events")
          .select("*")
          .eq("mosque_id", id)
          .gte("event_date", today)
          .order("event_date", { ascending: true })
          .limit(3),
        supabase
          .from("officer_schedules")
          .select("role, officers(name)")
          .eq("mosque_id", id)
          .eq("schedule_date", today),
        supabase.from("qris_settings").select("image_url").eq("mosque_id", id).single(),
        supabase.from("slides").select("*").eq("mosque_id", id).order("created_at", { ascending: false }),
      ]);

      if (annRes.data) setAnnouncements(annRes.data);
      if (evRes.data) setEvents(evRes.data);
      if (offRes.data)
        setOfficers(offRes.data.map((d: any) => ({ role: d.role, name: d.officers?.name || "-" })));
      if (qrisRes.data?.image_url) setQrisUrl(qrisRes.data.image_url);
      if (slidesRes.data) setSlides(slidesRes.data);
      if (mosqueData.city) await refreshPrayerTimes(mosqueData.city);
    };
    load();
  }, [slug, refreshPrayerTimes]);

  // Realtime subscriptions for announcements and events
  useEffect(() => {
    if (!mosque?.id) return;
    const id = mosque.id;
    const today = new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Jakarta" });

    const annChannel = supabase
      .channel(`mobile-ann-realtime-${id}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "announcements",
          filter: `mosque_id=eq.${id}`,
        },
        async (payload) => {
          const { data } = await supabase
            .from("announcements")
            .select("*")
            .eq("mosque_id", id)
            .order("created_at", { ascending: false })
            .limit(5);
          if (data) setAnnouncements(data);
          showLocalNotification("📢 Pengumuman Baru", payload.new.title);
        }
      )
      .subscribe();

    const evChannel = supabase
      .channel(`mobile-ev-realtime-${id}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "events",
          filter: `mosque_id=eq.${id}`,
        },
        async (payload) => {
          const { data } = await supabase
            .from("events")
            .select("*")
            .eq("mosque_id", id)
            .gte("event_date", today)
            .order("event_date", { ascending: true })
            .limit(3);
          if (data) setEvents(data);
          showLocalNotification(
            "🗓️ Agenda Kegiatan Baru",
            `${payload.new.title}${payload.new.speaker ? " bersama " + payload.new.speaker : ""}`
          );
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(annChannel);
      supabase.removeChannel(evChannel);
    };
  }, [mosque?.id]);

  // Clock
  useEffect(() => {
    const tick = () => {
      const now = new Date();
      setIsFriday(now.getDay() === 5);
      setTime(
        now.toLocaleTimeString("id-ID", { hour: "2-digit", minute: "2-digit", second: "2-digit" })
      );
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);

  // Auto slide
  useEffect(() => {
    if (slides.length === 0) return;
    const id = setInterval(() => setCurrentSlide((p) => (p + 1) % slides.length), 5000);
    return () => clearInterval(id);
  }, [slides.length]);

  const isRamadhan = new Date().toLocaleDateString("en-TN-u-ca-islamic").includes("Ramadan");
  const prayers = [
    ...(isRamadhan ? [{ name: "Imsak", time: prayerTimes?.Imsak }] : []),
    { name: "Subuh", time: prayerTimes?.Fajr },
    { name: "Dzuhur", time: prayerTimes?.Dhuhr },
    { name: "Ashar", time: prayerTimes?.Asr },
    { name: "Maghrib", time: prayerTimes?.Maghrib },
    { name: "Isya", time: prayerTimes?.Isha },
  ];

  // Countdown
  useEffect(() => {
    if (!prayerTimes) return;
    const update = () => {
      const now = new Date();
      let upcoming: { name: string; date: Date } | null = null;
      for (const p of prayers) {
        if (!p.time) continue;
        const [h, m] = p.time.split(":").map(Number);
        const d = new Date();
        d.setHours(h, m, 0, 0);
        if (d > now) {
          upcoming = { name: p.name, date: d };
          break;
        }
      }
      if (!upcoming && prayers[0]?.time) {
        const [h, m] = prayers[0].time.split(":").map(Number);
        const tomorrow = new Date();
        tomorrow.setDate(tomorrow.getDate() + 1);
        tomorrow.setHours(h, m, 0, 0);
        upcoming = { name: prayers[0].name, date: tomorrow };
      }
      if (!upcoming) return;
      const total = Math.floor((upcoming.date.getTime() - now.getTime()) / 1000);
      const hrs = Math.floor(total / 3600);
      const mins = Math.floor((total % 3600) / 60);
      const secs = total % 60;
      setNextPrayer(upcoming.name);
      setCountdown(
        `${String(hrs).padStart(2, "0")}:${String(mins).padStart(2, "0")}:${String(secs).padStart(
          2,
          "0"
        )}`
      );
    };
    update();
    const id = setInterval(update, 1000);
    return () => clearInterval(id);
  }, [prayerTimes]);

  // Auto adzan
  useEffect(() => {
    if (!prayerTimes) return;
    const adzanList = [
      { name: "Subuh", time: prayerTimes.Fajr, audio: "/audio/adzan-subuh.mp3" },
      { name: "Dzuhur", time: prayerTimes.Dhuhr, audio: "/audio/adzan.mp3" },
      { name: "Ashar", time: prayerTimes.Asr, audio: "/audio/adzan.mp3" },
      { name: "Maghrib", time: prayerTimes.Maghrib, audio: "/audio/adzan.mp3" },
      { name: "Isya", time: prayerTimes.Isha, audio: "/audio/adzan.mp3" },
    ];
    const id = setInterval(() => {
      const cur = new Date().toLocaleTimeString("id-ID", {
        hour: "2-digit",
        minute: "2-digit",
        hour12: false,
      });
      let isAnyPrayerNow = false;
      for (const p of adzanList) {
        const key = `${p.name}-${cur}`;
        if (cur === p.time) {
          isAnyPrayerNow = true;
          if (triggeredRef.current !== key) {
            triggeredRef.current = key;
            setShowAdzan(true);
            setCurrentPrayer(p.name);
            setIqomahCountdown(mosque?.iqomah_duration || 300);

            // Trigger push notification for adzan
            showLocalNotification(
              `🕌 Waktu Shalat ${p.name} Tiba`,
              `Adzan berkumandang. Mari menunaikan shalat ${p.name} berjamaah di ${
                mosque?.name || "Masjid"
              }.`
            );

            if (audioRef.current) {
              audioRef.current.src = p.audio;
              audioRef.current.volume = 1;
              audioRef.current.currentTime = 0;
              audioRef.current.play().catch((err) => {
                console.error("Gagal memutar adzan mobile:", err);
              });
            }
            setTimeout(() => setShowAdzan(false), 300000);
            break;
          }
        }
      }
      if (!isAnyPrayerNow) {
        triggeredRef.current = null;
      }
    }, 1000);
    return () => clearInterval(id);
  }, [prayerTimes, mosque]);

  // Cleanup audio on unmount
  useEffect(() => {
    return () => {
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current.currentTime = 0;
      }
    };
  }, []);

  // Iqomah countdown
  useEffect(() => {
    if (!showAdzan) return;
    const id = setInterval(() => {
      setIqomahCountdown((prev) => {
        if (prev <= 1) {
          clearInterval(id);
          setShowPrayerMode(true);
          setTimeout(() => setShowPrayerMode(false), 600000);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
    return () => clearInterval(id);
  }, [showAdzan]);

  const formatIqomah = (s: number) =>
    `${String(Math.floor(s / 60)).padStart(2, "0")}:${String(s % 60).padStart(2, "0")}`;

  if (notFound) {
    return (
      <main className="min-h-screen bg-slate-950 flex items-center justify-center text-white p-6 text-center">
        <div className="bg-slate-900/80 border border-emerald-500/20 rounded-3xl p-8 max-w-sm w-full shadow-2xl">
          <h1 className="text-6xl font-black text-amber-400 mb-4">404</h1>
          <p className="text-2xl font-bold text-slate-200 mb-2">Masjid Tidak Ditemukan</p>
          <p className="text-sm text-slate-400">Pastikan URL atau slug masjid yang Anda buka sudah benar.</p>
        </div>
      </main>
    );
  }

  if (!mosque) {
    return (
      <main className="min-h-screen bg-slate-950 flex items-center justify-center text-white">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-emerald-500 border-t-transparent rounded-full animate-spin" />
          <p className="text-lg font-bold text-emerald-400 tracking-wide">Memuat SmartMasjid...</p>
        </div>
      </main>
    );
  }

  if (showPrayerMode) {
    return (
      <main className="min-h-screen w-full bg-black flex items-center justify-center text-center p-8">
        <p className="text-4xl sm:text-5xl font-black text-amber-300 tracking-wide leading-relaxed max-w-lg drop-shadow-lg">
          {mosque?.shaf_message || "Harap rapatkan dan luruskan barisan shaf sholat"}
        </p>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-slate-950 text-slate-100 relative overflow-x-hidden selection:bg-amber-500 selection:text-black">
      {/* Background Texture & Glow */}
      <IslamicPatternBG />
      <div className="absolute -top-32 -left-32 w-80 h-80 bg-emerald-600/15 rounded-full blur-3xl pointer-events-none" />
      <div className="absolute top-1/3 -right-32 w-80 h-80 bg-amber-500/10 rounded-full blur-3xl pointer-events-none" />

      <div className="relative max-w-md mx-auto min-h-screen p-4 sm:p-6 flex flex-col gap-5 pb-12">
        {/* HEADER SECTION */}
        <header className="bg-gradient-to-r from-emerald-950/80 via-slate-900/90 to-emerald-950/80 backdrop-blur-xl border border-emerald-500/30 rounded-3xl p-4 sm:p-5 shadow-2xl shadow-emerald-950/60 relative overflow-hidden">
          {/* Top Gold Ornament Line */}
          <div className="absolute top-0 inset-x-0 h-1 bg-gradient-to-r from-amber-500/0 via-amber-400 to-amber-500/0" />

          {/* Bismillah Header */}
          <div className="text-center mb-3">
            <span className="text-amber-300 text-lg font-serif tracking-widest opacity-90">
              بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ
            </span>
          </div>

          <div className="flex items-center gap-4">
            {mosque.logo_url ? (
              <img
                src={mosque.logo_url}
                alt="Logo"
                className="w-16 h-16 sm:w-18 sm:h-18 rounded-2xl object-cover border-2 border-amber-400/80 bg-slate-900 shadow-lg shadow-amber-500/20 flex-shrink-0"
              />
            ) : (
              <div className="w-16 h-16 sm:w-18 sm:h-18 rounded-2xl border-2 border-amber-400/80 bg-emerald-900/60 flex items-center justify-center text-amber-300 flex-shrink-0 shadow-lg shadow-amber-500/20">
                <CrescentIcon className="w-9 h-9" />
              </div>
            )}

            <div className="flex-1 min-w-0">
              <h1 className="text-xl sm:text-2xl font-black text-amber-300 leading-tight truncate drop-shadow-sm">
                {mosque.name}
              </h1>
              {(mosque.city || mosque.province) && (
                <p className="text-sm font-medium text-slate-300 mt-1 flex items-center gap-1">
                  <span>📍</span>
                  <span className="truncate">
                    {[mosque.city, mosque.province].filter(Boolean).join(", ")}
                  </span>
                </p>
              )}
            </div>
          </div>

          {/* Clock & Date Banner */}
          <div className="mt-4 pt-3 border-t border-emerald-500/20 flex items-center justify-between">
            <div className="text-xs sm:text-sm font-semibold text-slate-300">
              {formatIndonesianDateWithDay(new Date())}
            </div>
            <div className="text-2xl sm:text-3xl font-black text-emerald-400 font-mono tracking-wider tabular-nums drop-shadow-md">
              {time}
            </div>
          </div>
        </header>

        {/* PUSH NOTIFICATION PROMPT BUTTON */}
        {push.isSupported && (
          <div className="bg-gradient-to-r from-emerald-900/40 via-slate-900/60 to-emerald-900/40 backdrop-blur-md border border-emerald-500/30 rounded-2xl p-3 sm:p-4 flex items-center justify-between gap-3 shadow-lg">
            <div className="flex items-center gap-3">
              <div className="w-10 h-10 rounded-xl bg-amber-500/20 border border-amber-400/40 flex items-center justify-center text-amber-300 text-xl flex-shrink-0">
                🔔
              </div>
              <div>
                <p className="text-sm font-bold text-white leading-snug">Notifikasi Waktu Sholat</p>
                <p className="text-xs text-slate-300">
                  {push.isSubscribed ? "Notifikasi adzan & kegiatan aktif" : "Dapatkan info adzan & kegiatan masjid"}
                </p>
              </div>
            </div>

            <button
              onClick={push.isSubscribed ? push.unsubscribe : push.subscribe}
              disabled={push.isLoading || push.isDenied}
              className={`px-4 py-2.5 rounded-xl font-bold text-xs sm:text-sm transition-all duration-300 flex-shrink-0 shadow-md ${
                push.isSubscribed
                  ? "bg-slate-800 text-emerald-300 border border-emerald-500/40 hover:bg-slate-700"
                  : push.isDenied
                  ? "bg-slate-800 text-slate-400 cursor-not-allowed"
                  : "bg-gradient-to-r from-amber-500 to-amber-600 hover:from-amber-400 hover:to-amber-500 text-slate-950 shadow-amber-500/30 active:scale-95"
              }`}
            >
              {push.isLoading ? "Proses..." : push.isSubscribed ? "Aktif ✓" : push.isDenied ? "Ditolak" : "Aktifkan"}
            </button>
          </div>
        )}

        {/* JUMAT MUBARAK BANNER */}
        {isFriday && (
          <div className="bg-gradient-to-r from-amber-500 via-amber-400 to-amber-500 text-slate-950 rounded-2xl p-4 text-center shadow-xl shadow-amber-500/20 border border-amber-300 relative overflow-hidden">
            <p className="text-lg font-black tracking-wide flex items-center justify-center gap-2">
              <span>🕌</span> JUMAT MUBARAK <span>✨</span>
            </p>
            <p className="text-xs sm:text-sm font-bold mt-1 opacity-90">
              Perbanyak Sholawat, Baca Surah Al-Kahfi & Datang Lebih Awal
            </p>
          </div>
        )}

        {/* MAIN COUNTDOWN / ADZAN DISPLAY CARD */}
        <div
          className={`rounded-3xl p-6 text-center transition-all duration-500 relative overflow-hidden shadow-2xl border ${
            showAdzan
              ? "bg-gradient-to-b from-amber-500 via-amber-600 to-amber-700 text-slate-950 border-amber-300 animate-pulse shadow-amber-500/40"
              : "bg-gradient-to-b from-emerald-900/90 via-slate-900/95 to-emerald-950/90 text-white border-emerald-500/40 backdrop-blur-xl shadow-emerald-950/80"
          }`}
        >
          {/* Subtle Arch Background */}
          <div className="absolute top-0 inset-x-0 h-2 bg-gradient-to-r from-transparent via-amber-400/60 to-transparent" />

          <p className="text-xs sm:text-sm font-extrabold uppercase tracking-widest text-amber-300 flex items-center justify-center gap-2">
            <span>✨</span>
            {showAdzan ? `WAKTU ADZAN ${currentPrayer}` : `MENUJUKAN ADZAN ${nextPrayer}`}
            <span>✨</span>
          </p>

          {/* Large Countdown Font for Mobile Readability */}
          <div className="my-3">
            <p className="text-5xl sm:text-6xl font-black tracking-wider font-mono text-amber-300 drop-shadow-lg tabular-nums">
              {countdown}
            </p>
          </div>

          {showAdzan && (
            <div className="mt-3 bg-slate-950/30 rounded-2xl p-3 border border-slate-950/40">
              <p className="text-base font-extrabold text-slate-950 animate-bounce">
                Hayya &apos;alash Shalah — 📵 Harap Matikan / Eningkan HP
              </p>
            </div>
          )}

          {/* Iqomah Counter */}
          <div className="mt-4 pt-3 border-t border-emerald-500/20 flex items-center justify-center gap-3">
            <span className="text-xs sm:text-sm font-bold text-slate-300 uppercase tracking-wider">
              Jeda Iqomah:
            </span>
            <span className="text-2xl font-black text-emerald-400 font-mono tracking-wide">
              {formatIqomah(iqomahCountdown)}
            </span>
          </div>
        </div>

        {/* JADWAL SHOLAT GRID (PROMINENT & LARGE FONT) */}
        {prayerTimes && (
          <div className="space-y-2">
            <h2 className="text-base font-extrabold text-amber-400 uppercase tracking-wider flex items-center gap-2">
              <CrescentIcon className="w-5 h-5 text-amber-400" />
              Jadwal Sholat Hari Ini
            </h2>

            <div className="grid grid-cols-3 gap-2.5 sm:gap-3">
              {prayers.map((p) => {
                const isNext = p.name === nextPrayer;
                return (
                  <div
                    key={p.name}
                    className={`rounded-2xl p-3.5 sm:p-4 text-center transition-all duration-300 border ${
                      isNext
                        ? "bg-gradient-to-b from-amber-500/20 via-slate-900 to-amber-950/30 border-amber-400 shadow-lg shadow-amber-500/20 scale-[1.02]"
                        : "bg-slate-900/80 border-emerald-500/20 hover:border-emerald-500/40"
                    }`}
                  >
                    <p
                      className={`text-xs sm:text-sm font-extrabold uppercase tracking-wide ${
                        isNext ? "text-amber-300" : "text-emerald-400"
                      }`}
                    >
                      {p.name}
                    </p>
                    <p className="text-xl sm:text-2xl font-black text-white mt-1 font-mono tracking-tight tabular-nums">
                      {p.time || "-"}
                    </p>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* SLIDER BANNER */}
        {slides.length > 0 && (
          <div className="rounded-3xl overflow-hidden h-52 sm:h-60 relative border border-emerald-500/30 shadow-xl">
            <img
              src={slides[currentSlide]?.image_url}
              alt="Slide"
              className="w-full h-full object-cover"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-transparent to-transparent opacity-80" />
            {slides.length > 1 && (
              <div className="absolute bottom-3 left-1/2 -translate-x-1/2 flex gap-1.5 bg-slate-950/60 backdrop-blur-md px-3 py-1.5 rounded-full border border-white/10">
                {slides.map((_, i) => (
                  <div
                    key={i}
                    className={`h-2 rounded-full transition-all duration-300 ${
                      i === currentSlide ? "w-6 bg-amber-400" : "w-2 bg-white/40"
                    }`}
                  />
                ))}
              </div>
            )}
          </div>
        )}

        {/* DONASI QRIS SECTION */}
        {qrisUrl && (
          <div className="bg-gradient-to-b from-slate-900/90 to-emerald-950/80 backdrop-blur-xl border border-emerald-500/30 rounded-3xl p-5 flex flex-col items-center gap-4 text-center shadow-xl">
            <h2 className="text-lg font-extrabold text-amber-300 flex items-center gap-2">
              <span>💳</span> Infaq & Donasi Masjid
            </h2>
            <div className="bg-white p-3 rounded-2xl shadow-xl border-2 border-amber-400/60">
              <img src={qrisUrl} alt="QRIS Donasi" className="w-52 h-52 object-contain" />
            </div>
            <p className="text-xs sm:text-sm font-medium text-slate-300 max-w-xs leading-relaxed">
              Scan kode QRIS di atas melalui mobile banking atau e-wallet (Gopay, OVO, Dana, ShopeePay) Anda.
            </p>
          </div>
        )}

        {/* PETUGAS HARI INI */}
        {officers.length > 0 && (
          <div className="bg-slate-900/80 backdrop-blur-xl border border-emerald-500/20 rounded-3xl p-5 shadow-xl">
            <h2 className="text-base sm:text-lg font-extrabold text-amber-300 mb-3.5 flex items-center gap-2">
              <span>🕌</span> Petugas Sholat Hari Ini
            </h2>
            <div className="grid gap-2.5">
              {officers.map((o, i) => (
                <div
                  key={i}
                  className="flex items-center justify-between bg-slate-950/70 border border-emerald-500/10 rounded-2xl px-4 py-3"
                >
                  <span className="text-xs sm:text-sm font-extrabold text-amber-400 uppercase tracking-wide">
                    {o.role}
                  </span>
                  <span className="text-sm sm:text-base font-bold text-slate-100">{o.name}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* JADWAL KEGIATAN */}
        {events.length > 0 && (
          <div className="bg-slate-900/80 backdrop-blur-xl border border-emerald-500/20 rounded-3xl p-5 shadow-xl">
            <h2 className="text-base sm:text-lg font-extrabold text-amber-300 mb-3.5 flex items-center gap-2">
              <span>🗓️</span> Agenda & Kegiatan Masjid
            </h2>
            <div className="grid gap-3">
              {events.map((item) => (
                <div
                  key={item.id}
                  className="bg-slate-950/70 border border-emerald-500/20 rounded-2xl p-4 relative overflow-hidden"
                >
                  <div className="absolute top-0 left-0 w-1.5 h-full bg-amber-400" />
                  <p className="text-base sm:text-lg font-bold text-white">{item.title}</p>
                  {item.speaker && (
                    <p className="text-sm font-semibold text-emerald-300 mt-1">
                      🗣️ penceramah: {item.speaker}
                    </p>
                  )}
                  <p className="text-xs sm:text-sm font-medium text-slate-400 mt-2 flex items-center gap-2">
                    <span>📅 {formatIndonesianDateWithDay(item.event_date)}</span>
                    <span>•</span>
                    <span>⏰ {item.event_time}</span>
                  </p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* PENGUMUMAN */}
        {announcements.length > 0 && (
          <div className="bg-slate-900/80 backdrop-blur-xl border border-emerald-500/20 rounded-3xl p-5 shadow-xl">
            <h2 className="text-base sm:text-lg font-extrabold text-amber-300 mb-3.5 flex items-center gap-2">
              <span>📢</span> Pengumuman Masjid
            </h2>
            <div className="grid gap-3">
              {announcements.map((item) => (
                <div
                  key={item.id}
                  className="bg-slate-950/70 border border-emerald-500/20 rounded-2xl p-4"
                >
                  <p className="text-sm sm:text-base font-bold text-slate-100 leading-relaxed">
                    {item.title}
                  </p>
                  {item.content && (
                    <p className="text-xs sm:text-sm text-slate-300 mt-2 leading-normal">
                      {item.content}
                    </p>
                  )}
                </div>
              ))}
            </div>
          </div>
        )}

        {/* RUNNING TEXT */}
        {mosque.running_text && (
          <div className="overflow-hidden bg-gradient-to-r from-emerald-950 via-slate-900 to-emerald-950 border border-emerald-500/30 rounded-2xl py-3 shadow-lg">
            <div
              className="text-sm sm:text-base font-bold text-amber-300 whitespace-nowrap inline-block tracking-wide"
              style={{
                paddingLeft: "100%",
                animation: `marquee ${mosque.running_text_speed || 20}s linear infinite`,
              }}
            >
              {mosque.running_text}
            </div>
          </div>
        )}

        {/* FOOTER BRANDING */}
        <footer className="text-center pt-4 text-xs font-semibold text-slate-300 space-y-1">
          <p>SmartMasjid Mobile Portal</p>
          <p className="text-[11px] text-emerald-400/90 font-mono">
            {mosque.name} • {new Date().getFullYear()}
          </p>
        </footer>
      </div>

      <audio ref={audioRef} src="/audio/adzan.mp3" />

      <style jsx>{`
        @keyframes marquee {
          0% {
            transform: translateX(0%);
          }
          100% {
            transform: translateX(-100%);
          }
        }
      `}</style>
    </main>
  );
}

items.Text:
"use client";

/**
 * SmartMasjid Mobile — Home Screen
 *
 * Performance architecture:
 * - Clock/countdown runs in an isolated client island (ClockWidget)
 *   so the 1-second tick does NOT re-render the whole page.
 * - All display components are direct imports (no dynamic() splitting)
 *   so Tailwind styles are available immediately — no FOUC.
 * - next/image used for mosque logo and QRIS for lazy loading + CLS prevention.
 * - All data fetched in parallel via Promise.all.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import Image from "next/image";
import { useRouter } from "next/navigation";
import { useFavoriteMosque } from "@/hooks/useFavoriteMosque";
import { usePushNotification } from "@/hooks/usePushNotification";

// ── Services ─────────────────────────────────────────────────────────────
import { getMosqueBySlug }            from "@/lib/mobile/mosque";
import { getAnnouncements }           from "@/lib/mobile/announcement";
import { getUpcomingEvents }          from "@/lib/mobile/event";
import { getTodayOfficers }           from "@/lib/mobile/officer";
import { getSlides, getQrisImageUrl } from "@/lib/mobile/slides";
import {
  fetchPrayerTimesForCity,
  buildSholatList,
  getNextPrayerCountdown,
  decoratePrayerList,
  formatIqomah,
} from "@/lib/mobile/prayer";

// ── Types ─────────────────────────────────────────────────────────────────
import type {
  MosqueRow,
  AnnouncementRow,
  EventRow,
  OfficerEntry,
  SlideRow,
  PrayerEntry,
} from "@/lib/mobile/types";

// ── Components — ALL direct imports so CSS is never delayed ──────────────
import MobileHeader     from "./components/mobile/MobileHeader";
import ClockWidget, { CountdownBar } from "./components/mobile/ClockWidget";
import PrayerCard       from "./components/mobile/PrayerCard";
import AnnouncementCard from "./components/mobile/AnnouncementCard";
import EventCard        from "./components/mobile/EventCard";
import QuickAction, { QuickActionItem } from "./components/mobile/QuickAction";
import SkeletonHome     from "./components/mobile/SkeletonHome";
import SlideShow        from "./components/mobile/SlideShow";
import RunningText      from "./components/mobile/RunningText";
import QrisCard         from "./components/mobile/QrisCard";
import OfficerStrip     from "./components/mobile/OfficerStrip";
import LocationCard     from "./components/mobile/LocationCard";
import ContactCard      from "./components/mobile/ContactCard";
import LiveTVButton     from "./components/mobile/LiveTVButton";
import PageTransition   from "./components/mobile/PageTransition";
import PullToRefresh    from "./components/mobile/PullToRefresh";

import { QrCode, MapPin, Clock, Tv2 } from "lucide-react";

// ─── Types ────────────────────────────────────────────────────────────────

type LoadState = "idle" | "loading" | "ready" | "error" | "not_found";

// ─── Page ─────────────────────────────────────────────────────────────────

export default function AppHomePage() {
  const router = useRouter();
  const { state: favState, favorite, clearMosque } = useFavoriteMosque();

  // Redirect to select-mosque if no favorite mosque is set
  useEffect(() => {
    if (favState === "not_found") {
      router.replace("/app/select-mosque");
    }
  }, [favState, router]);

  const slug = favorite?.slug ?? "";

  const [loadState, setLoadState]         = useState<LoadState>("idle");
  const [mosque, setMosque]               = useState<MosqueRow | null>(null);
  const [prayers, setPrayers]             = useState<PrayerEntry[]>([]);
  const [syuruqTime, setSyuruqTime]       = useState("");
  const [prayerTimings, setPrayerTimings] = useState<Record<string, string> | null>(null);
  const [announcements, setAnnouncements] = useState<AnnouncementRow[]>([]);
  const [events, setEvents]               = useState<EventRow[]>([]);
  const [officers, setOfficers]           = useState<OfficerEntry[]>([]);
  const [slides, setSlides]               = useState<SlideRow[]>([]);
  const [qrisUrl, setQrisUrl]             = useState<string | null>(null);

  const push = usePushNotification(mosque?.id);

  const [iqomahSecs, setIqomahSecs]           = useState(300);
  const [showAdzan, setShowAdzan]             = useState(false);
  const [currentPrayer, setCurrentPrayer]     = useState("");

  const audioRef     = useRef<HTMLAudioElement | null>(null);
  const triggeredRef = useRef<string | null>(null);

  // Load prayer times helper
  const loadPrayerTimes = useCallback(async (city: string) => {
    const timings = await fetchPrayerTimesForCity(city);
    if (!timings) return;
    setPrayerTimings(timings);
    setPrayers(buildSholatList(timings));
    setSyuruqTime(timings.Sunrise ?? "");
  }, []);

  // Main data load — re-runs whenever the favorite mosque slug changes
  useEffect(() => {
    if (favState === "loading" || !slug) return;

    setLoadState("loading");

    // Reset state when switching mosques
    setMosque(null);
    setPrayers([]);
    setSyuruqTime("");
    setPrayerTimings(null);
    setAnnouncements([]);
    setEvents([]);
    setOfficers([]);
    setSlides([]);
    setQrisUrl(null);
    setShowAdzan(false);

    (async () => {
      try {
        const mosqueData = await getMosqueBySlug(slug);
        if (!mosqueData) { setLoadState("not_found"); return; }

        setMosque(mosqueData);
        if (mosqueData.iqomah_duration) setIqomahSecs(mosqueData.iqomah_duration as number);

        const id = mosqueData.id;

        const [ann, ev, off, sli, qris] = await Promise.all([
          getAnnouncements(id),
          getUpcomingEvents(id),
          getTodayOfficers(id),
          getSlides(id),
          getQrisImageUrl(id),
        ]);

        setAnnouncements(ann);
        setEvents(ev);
        setOfficers(off);
        setSlides(sli);
        setQrisUrl(qris);

        if (mosqueData.city) await loadPrayerTimes(mosqueData.city as string);

        setLoadState("ready");
      } catch {
        setLoadState("error");
      }
    })();
  }, [slug, favState, loadPrayerTimes]);

  // Auto adzan (same logic as TV Display)
  useEffect(() => {
    if (!prayerTimings) return;
    const list = [
      { name: "Subuh",   time: prayerTimings.Fajr,    audio: "/audio/adzan-subuh.mp3" },
      { name: "Dzuhur",  time: prayerTimings.Dhuhr,   audio: "/audio/adzan.mp3" },
      { name: "Ashar",   time: prayerTimings.Asr,     audio: "/audio/adzan.mp3" },
      { name: "Maghrib", time: prayerTimings.Maghrib, audio: "/audio/adzan.mp3" },
      { name: "Isya",    time: prayerTimings.Isha,    audio: "/audio/adzan.mp3" },
    ];
    const id = setInterval(() => {
      const cur = new Date().toLocaleTimeString("id-ID", { hour: "2-digit", minute: "2-digit", hour12: false });
      for (const p of list) {
        const key = `${p.name}-${cur}`;
        if (cur === p.time && triggeredRef.current !== key) {
          triggeredRef.current = key;
          setShowAdzan(true);
          setCurrentPrayer(p.name);
          setIqomahSecs(mosque?.iqomah_duration ?? 300);
          const audio = new Audio(p.audio);
          audioRef.current = audio;
          audio.play().catch(() => {});
          setTimeout(() => setShowAdzan(false), 300_000);
          break;
        }
      }
    }, 1000);
    return () => clearInterval(id);
  }, [prayerTimings, mosque]);

  // Iqomah countdown
  useEffect(() => {
    if (!showAdzan) return;
    const id = setInterval(() => setIqomahSecs((p) => (p <= 1 ? 0 : p - 1)), 1000);
    return () => clearInterval(id);
  }, [showAdzan]);

  // Derived values
  const decoratedPrayers = decoratePrayerList(
    prayers,
    prayers.length > 0 ? getNextPrayerCountdown(prayers).name : ""
  );
  const locationText = [mosque?.city, mosque?.province].filter(Boolean).join(", ");
  const today = new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Jakarta" });

  const announcementItems = announcements.map((a) => ({
    id: a.id,
    title: a.title,
    createdAt: new Date(a.created_at).toLocaleDateString("id-ID", {
      day: "numeric", month: "short", year: "numeric",
    }),
  }));

  const eventItems = events.map((e) => ({
    id: e.id,
    title: e.title,
    speaker: e.speaker ?? undefined,
    eventDate: e.event_date,
    eventTime: e.event_time ?? undefined,
    isToday: e.event_date === today,
  }));

  const quickActions: QuickActionItem[] = [
    {
      id: "sholat",
      label: "Jadwal Sholat",
      sublabel: "Waktu sholat",
      icon: Clock,
      variant: "emerald",
      href: "/app/sholat",
    },
    {
      id: "donasi",
      label: "Donasi",
      sublabel: "Infaq & QRIS",
      icon: QrCode,
      variant: "yellow",
      href: "/app/donasi",
    },
    {
      id: "info",
      label: "Informasi",
      sublabel: "Pengumuman",
      icon: MapPin,
      variant: "purple",
      href: "/app/info",
    },
    {
      id: "tv",
      label: "TV Display",
      sublabel: "Layar masjid",
      icon: Tv2,
      variant: "blue",
      href: slug ? `/tv/${slug}` : "/app",
    },
  ];

  // ─── Render states ────────────────────────────────────────────────

  // Still reading localStorage or waiting for redirect
  if (favState === "loading" || favState === "not_found" || !slug) {
    return <SkeletonHome />;
  }

  if (loadState === "loading" || loadState === "idle") {
    return <SkeletonHome />;
  }

  if (loadState === "not_found") {
    return (
      <main
        className="min-h-screen flex flex-col items-center justify-center gap-4 px-8 text-center"
        style={{ background: "var(--pwa-bg)" }}
        role="alert"
      >
        <div className="text-5xl" role="img" aria-label="Sedih">😔</div>
        <h1 className="text-xl font-bold" style={{ color: "var(--pwa-text-primary)" }}>Masjid Tidak Ditemukan</h1>
        <p className="text-sm" style={{ color: "var(--pwa-text-muted)" }}>
          Masjid dengan slug <span className="text-amber-400 font-mono">{slug}</span> tidak ditemukan di database.
        </p>
        <div className="rounded-xl px-4 py-3 mt-2 max-w-sm" style={{ background: "var(--pwa-bg-card)" }}>
          <p className="text-xs leading-relaxed" style={{ color: "var(--pwa-text-secondary)" }}>
            Kemungkinan penyebab:
          </p>
          <ul className="text-xs text-left mt-2 space-y-1" style={{ color: "var(--pwa-text-muted)" }}>
            <li>• Masjid belum terdaftar atau dihapus</li>
            <li>• Slug berubah setelah update</li>
            <li>• Data lama tersimpan di perangkat</li>
          </ul>
        </div>
        <button
          type="button"
          onClick={() => {
            clearMosque();
            router.replace("/app/select-mosque");
          }}
          className="mt-4 bg-emerald-500 text-black font-bold px-6 py-3 rounded-2xl active:bg-emerald-600 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-400"
          aria-label="Pilih masjid lain"
        >
          Pilih Masjid Lain
        </button>
      </main>
    );
  }

  if (loadState === "error") {
    return (
      <main
        className="min-h-screen flex flex-col items-center justify-center gap-4 px-8 text-center"
        style={{ background: "var(--pwa-bg)" }}
        role="alert"
      >
        <div className="text-5xl" role="img" aria-label="Peringatan">⚠️</div>
        <h1 className="text-xl font-bold" style={{ color: "var(--pwa-text-primary)" }}>Gagal Memuat Data</h1>
        <p className="text-sm" style={{ color: "var(--pwa-text-muted)" }}>Periksa koneksi internet dan coba lagi.</p>
        <button
          type="button"
          onClick={() => window.location.reload()}
          className="mt-2 bg-emerald-500 text-black font-bold px-6 py-3 rounded-2xl active:bg-emerald-600 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-400"
        >
          Coba Lagi
        </button>
      </main>
    );
  }

  // ─── Full home screen ─────────────────────────────────────────────

  return (
    <PageTransition variant="slide-up">
      <PullToRefresh onRefresh={async () => { window.location.reload(); }}>
    <div className={`min-h-screen transition-colors duration-500 ${showAdzan ? "bg-yellow-950" : ""}`}
      style={!showAdzan ? { background: "var(--pwa-bg)" } : undefined}
    >

      {/* ── 1. Header ─────────────────────────────────────────────── */}
      <MobileHeader
        mosqueName={mosque?.name}
        logoUrl={mosque?.logo_url ?? undefined}
        location={locationText || undefined}
      />

      {/* ── 2. Hero — mosque identity + clock island ──────────────── */}
      <section className="relative overflow-hidden px-5 pt-6 pb-5" aria-label="Informasi Masjid">
        {/* Ambient orbs — decorative only */}
        <div className="absolute inset-0 pointer-events-none select-none overflow-hidden" aria-hidden="true">
          <div className="absolute -top-10 -right-10 w-48 h-48 rounded-full bg-emerald-500/5 blur-2xl" />
          <div className="absolute -bottom-6 -left-6 w-36 h-36 rounded-full bg-yellow-500/5 blur-2xl" />
        </div>

        {/* Mosque identity */}
        <div className="relative z-10 flex items-center gap-4 mb-5">
          {mosque?.logo_url ? (
            <Image
              src={mosque.logo_url}
              alt={`Logo ${mosque.name}`}
              width={56}
              height={56}
              className="rounded-2xl object-cover border-2 border-emerald-400 shrink-0"
              priority
              unoptimized={mosque.logo_url.startsWith("http")}
            />
          ) : (
            <div
              className="w-14 h-14 rounded-2xl bg-gradient-to-br from-emerald-600 to-emerald-800 border-2 border-emerald-400/60 flex items-center justify-center shrink-0"
              aria-hidden="true"
            >
              <span className="text-2xl">🕌</span>
            </div>
          )}

          <div>
            <h1 className="text-xl font-extrabold leading-tight" style={{ color: "var(--pwa-text-primary)" }}>{mosque?.name}</h1>
            {mosque?.tagline && (
              <p className="text-xs mt-0.5 italic leading-snug" style={{ color: "var(--pwa-text-muted)" }}>{mosque.tagline}</p>
            )}
            {locationText && (
              <p className="text-xs text-emerald-400 font-medium mt-0.5">{locationText}</p>
            )}
          </div>
        </div>

        {/* Clock island — only this re-renders every second */}
        <div className="relative z-10">
          <ClockWidget
            prayers={prayers}
            iqomahSecs={iqomahSecs}
            showAdzan={showAdzan}
            currentPrayer={currentPrayer}
          />
        </div>
      </section>

      {/* ── 3. Countdown bar ──────────────────────────────────────── */}
      <div className="mt-1 mb-4">
        <CountdownBar
          prayers={prayers}
          iqomahSecs={iqomahSecs}
          showAdzan={showAdzan}
          currentPrayer={currentPrayer}
        />
      </div>

      {/* ── Push Notification Card ───────────────────────────────── */}
      {push.isSupported && (
        <div className="mx-4 sm:mx-5 mb-5 bg-gradient-to-r from-emerald-900/40 via-slate-900/60 to-emerald-900/40 backdrop-blur-md border border-emerald-500/30 rounded-2xl p-3.5 sm:p-4 flex items-center justify-between gap-3 shadow-lg">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-amber-500/20 border border-amber-400/40 flex items-center justify-center text-amber-300 text-xl shrink-0">
              🔔
            </div>
            <div>
              <p className="text-sm font-bold leading-snug" style={{ color: "var(--pwa-text-primary)" }}>Notifikasi Waktu Sholat</p>
              <p className="text-xs" style={{ color: "var(--pwa-text-secondary)" }}>
                {push.isSubscribed ? "Notifikasi adzan & kegiatan aktif" : "Dapatkan info adzan & kegiatan masjid"}
              </p>
            </div>
          </div>

          <button
            onClick={push.isSubscribed ? push.unsubscribe : push.subscribe}
            disabled={push.isLoading || push.isDenied}
            className={`px-4 py-2.5 rounded-xl font-bold text-xs sm:text-sm transition-all duration-300 shrink-0 shadow-md ${
              push.isSubscribed
                ? "bg-slate-800 text-emerald-300 border border-emerald-500/40 hover:bg-slate-700"
                : push.isDenied
                ? "bg-slate-800 text-slate-400 cursor-not-allowed"
                : "bg-gradient-to-r from-amber-500 to-amber-600 hover:from-amber-400 hover:to-amber-500 text-slate-950 shadow-amber-500/30 active:scale-95"
            }`}
          >
            {push.isLoading ? "Proses..." : push.isSubscribed ? "Aktif ✓" : push.isDenied ? "Ditolak" : "Aktifkan"}
          </button>
        </div>
      )}

      {/* ── 4. Quick actions ──────────────────────────────────────── */}
      <QuickAction actions={quickActions} />

      {/* ── 5. Prayer grid ────────────────────────────────────────── */}
      {prayers.length > 0 && (
        <div className="mt-5">
          <PrayerCard prayers={decoratedPrayers} syuruqTime={syuruqTime} />
        </div>
      )}

      {/* ── 6. Slide show ─────────────────────────────────────────── */}
      {slides.length > 0 && <SlideShow slides={slides} />}

      {/* ── 7. Officers ───────────────────────────────────────────── */}
      <OfficerStrip officers={officers} />

      {/* ── 8. Announcements ──────────────────────────────────────── */}
      <div className="mt-5">
        <AnnouncementCard announcements={announcementItems} />
      </div>

      {/* ── 9. Events ─────────────────────────────────────────────── */}
      <div className="mt-5">
        <EventCard events={eventItems} />
      </div>

      {/* ── 10. Running text ──────────────────────────────────────── */}
      {mosque?.running_text && (
        <RunningText text={mosque.running_text} speed={mosque.running_text_speed ?? 20} />
      )}

      {/* ── 11. QRIS ──────────────────────────────────────────────── */}
      {qrisUrl && (
        <div id="section-qris">
          <QrisCard imageUrl={qrisUrl} mosqueName={mosque?.name} />
        </div>
      )}

      {/* ── 12. Location ──────────────────────────────────────────── */}
      <div id="section-location">
        <LocationCard
          address={mosque?.address ?? null}
          city={mosque?.city ?? null}
          province={mosque?.province ?? null}
          mosqueName={mosque?.name}
        />
      </div>

      {/* ── 13. Contact ───────────────────────────────────────────── */}
      <div id="section-contact">
        <ContactCard
          phone={mosque?.phone ?? null}
          whatsapp={mosque?.whatsapp ?? null}
          website={mosque?.website ?? null}
          email={mosque?.email ?? null}
        />
      </div>

      {/* ── 14. Live TV button ────────────────────────────────────── */}
      {mosque?.slug && <LiveTVButton slug={mosque.slug} />}

      {/* Hidden audio */}
      {/* eslint-disable-next-line jsx-a11y/media-has-caption */}
      <audio ref={audioRef} src="/audio/adzan.mp3" aria-hidden="true" />

      <div className="h-8" aria-hidden="true" />
    </div>
      </PullToRefresh>
    </PageTransition>
  );
}

"use client";

/**
 * SmartMasjid Mobile — Profile Page (/app/profil)
 *
 * Displays:
 * - Mosque logo, name, tagline, address, contact, website
 * - "Masjid Saya" with Ganti Masjid button
 *
 * Ganti Masjid flow:
 *   Click "Ganti Masjid" → sets sessionStorage intent → router.push("/app/select-mosque")
 *   After user picks in select-mosque page → router.replace("/app")
 */

import { useCallback, useEffect, useState } from "react";
import { useRouter }     from "next/navigation";
import Image             from "next/image";
import {
  MapPin, Phone, MessageCircle, Globe, Mail,
  RefreshCw, Tv2, Building2, Info, Clock,
  ExternalLink, ChevronRight, Bell, BellOff,
  Sun, Moon, Monitor, Timer,
} from "lucide-react";

import { useTheme } from "@/lib/themes/ThemeProvider";
import type { ThemeMode } from "@/lib/themes/ThemeProvider";

import { usePushNotification } from "@/hooks/usePushNotification";

import { useFavoriteMosque }  from "@/hooks/useFavoriteMosque";
import { getMosqueBySlug }    from "@/lib/mobile/mosque";
import type { MosqueRow }     from "@/lib/mobile/types";

import { SkeletonProfile }   from "../components/mobile/Skeleton";
import ErrorState            from "../components/mobile/ErrorState";
import PullToRefresh         from "../components/mobile/PullToRefresh";
import PageTransition        from "../components/mobile/PageTransition";

// ─── Types ─────────────────────────────────────────────────────────────────

type LoadState = "idle" | "loading" | "ready" | "error";

// ─── Page ──────────────────────────────────────────────────────────────────

export default function ProfilPage() {
  const router = useRouter();
  const { state: favState, favorite, recent, selectMosque } = useFavoriteMosque();

  const { theme: activeTheme, setTheme } = useTheme();

  const [loadState, setLoadState] = useState<LoadState>("idle");
  const [mosque,    setMosque]    = useState<MosqueRow | null>(null);
  const [switching, setSwitching] = useState(false);

  // Push notification subscription
  const {
    isSupported: pushSupported,
    isSubscribed,
    isLoading: pushLoading,
    isDenied: pushDenied,
    status: pushStatus,
    errorMsg: pushErrorMsg,
    subscribe: subscribePush,
    unsubscribe: unsubscribePush,
  } = usePushNotification(favorite?.mosque_id ?? null);

  // Redirect if no mosque set
  useEffect(() => {
    if (favState === "not_found") router.replace("/app/select-mosque");
  }, [favState, router]);

  const slug = favorite?.slug ?? "";

  const loadData = useCallback(async () => {
    if (!slug || favState === "loading") return;
    setLoadState("loading");
    try {
      const mosqueData = await getMosqueBySlug(slug);
      if (!mosqueData) { setLoadState("error"); return; }
      setMosque(mosqueData);
      setLoadState("ready");
    } catch {
      setLoadState("error");
    }
  }, [slug, favState]);

  useEffect(() => { loadData(); }, [loadData]);

  /** Ganti Masjid — open the fullscreen select-mosque page */
  const handleGantiMasjid = useCallback(() => {
    // Set intent flag so select-mosque knows not to auto-redirect back to /app
    sessionStorage.setItem("select_mosque_intent", "ganti");
    router.push("/app/select-mosque");
  }, [router]);

  /** Switch directly to a mosque from the recent list */
  const handleChangeMosque = useCallback(async (picked: MosqueRow) => {
    if (switching) return;
    setSwitching(true);
    selectMosque(picked);
    router.replace("/app");
  }, [switching, selectMosque, router]);

  const handleRefresh = useCallback(async () => {
    await loadData();
  }, [loadData]);

  const locationText = [mosque?.city, mosque?.province].filter(Boolean).join(", ");
  const mapsQuery    = encodeURIComponent(
    [mosque?.name, mosque?.address, mosque?.city].filter(Boolean).join(", ")
  );
  const mapsUrl = `https://www.google.com/maps/search/?api=1&query=${mapsQuery}`;

  // ─── Render states ──────────────────────────────────────────────────

  if (favState === "loading" || loadState === "idle" || loadState === "loading") {
    return <SkeletonProfile />;
  }

  if (loadState === "error") {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center px-5">
        <ErrorState onRetry={loadData} />
      </div>
    );
  }

  return (
    <>
      <PageTransition variant="slide-up">
        <PullToRefresh onRefresh={handleRefresh}>
          <div className="min-h-screen bg-slate-950">

            {/* ── Header ──────────────────────────────────────────── */}
            <header
              className="sticky top-0 z-40 bg-slate-950/90 backdrop-blur-xl border-b border-slate-800"
              style={{ paddingTop: "env(safe-area-inset-top)" }}
            >
              <div className="px-5 py-4 flex items-center justify-between">
                <h1 className="text-base font-bold text-white">Profil</h1>
                <div className="flex items-center gap-1.5 bg-emerald-500/10 border border-emerald-500/20 rounded-full px-2.5 py-1">
                  <span className="text-[10px] font-bold text-emerald-400 uppercase tracking-wide">
                    SmartMasjid
                  </span>
                </div>
              </div>
              <div className="h-px bg-gradient-to-r from-transparent via-emerald-500/30 to-transparent" aria-hidden="true" />
            </header>

            <div className="px-5 pt-5 pb-32 space-y-5">

              {/* ── Mosque Identity Card ───────────────────────────── */}
              {mosque && (
                <section aria-label="Identitas masjid">
                  <div className="relative overflow-hidden rounded-3xl bg-gradient-to-br from-slate-800 to-slate-900 border border-slate-700/40">
                    {/* Ambient orb */}
                    <div
                      className="absolute -top-10 -right-10 w-48 h-48 rounded-full bg-emerald-500/8 blur-2xl pointer-events-none"
                      aria-hidden="true"
                    />

                    <div className="relative z-10 px-5 pt-5 pb-4">
                      {/* Logo + name */}
                      <div className="flex items-center gap-4 mb-4">
                        {mosque.logo_url ? (
                          <Image
                            src={mosque.logo_url}
                            alt={`Logo ${mosque.name}`}
                            width={72}
                            height={72}
                            className="w-18 h-18 rounded-2xl object-cover border-2 border-emerald-400/60 shrink-0"
                            priority
                            unoptimized={mosque.logo_url.startsWith("http")}
                          />
                        ) : (
                          <div
                            className="w-[72px] h-[72px] rounded-2xl bg-gradient-to-br from-emerald-600 to-emerald-800 border-2 border-emerald-400/60 flex items-center justify-center shrink-0"
                            aria-hidden="true"
                          >
                            <span className="text-3xl">🕌</span>
                          </div>
                        )}

                        <div className="flex-1 min-w-0">
                          <h2 className="text-white font-extrabold text-lg leading-tight">
                            {mosque.name}
                          </h2>
                          {mosque.tagline && (
                            <p className="text-slate-400 text-xs mt-1 italic leading-snug">
                              {mosque.tagline}
                            </p>
                          )}
                          {locationText && (
                            <div className="flex items-center gap-1 mt-1.5">
                              <MapPin size={11} className="text-emerald-400 shrink-0" strokeWidth={2} aria-hidden="true" />
                              <span className="text-emerald-400 text-xs font-medium truncate">
                                {locationText}
